document.querySelector('#organic').onclick=async()=>{const r=await api('/api/mark-organic');if(!r.ok)alert(await r.text());};
const fullProtectionButton=document.querySelector('#fullProtectionButton');if(fullProtectionButton)fullProtectionButton.onclick=async()=>{if(!confirm('Enable Full Protection? StreamShield does not store full viewer IPs. It keeps only a keyed one-way network identifier when viewers use a verification link. Targeted Channel Verification also uses a random first-party browser token whose hashed form is retained for up to 90 days. Exact blocked-network matches can be automatically banned; device-token matches require moderator review by default. Shared or reassigned IPs can cause false positives.'))return;const r=await api('/api/network-protection',{enabled:true,autoBanExactNetworkMatch:true});if(!r.ok)alert(await r.text());};
